// QueryServer is the server API for Query service.
type QueryServer interface {
	// Invariants returns the values in force. This is the query a supervisor runs
	// to find out what the chain has promised not to change, so it answers with
	// the whole settlement rather than a field at a time.
	Invariants(context.Context, *QueryInvariantsRequest) (*QueryInvariantsResponse, error)
	// Amendment queries one amendment by id.
	Amendment(context.Context, *QueryAmendmentRequest) (*QueryAmendmentResponse, error)
	// ListAmendment queries every amendment ever opened, lapsed and withdrawn
	// ones included.
	ListAmendment(context.Context, *QueryAllAmendmentRequest) (*QueryAllAmendmentResponse, error)
	// Ratifications lists who has ratified one amendment, which is the record
	// that makes a validator answerable for a change it agreed to.
	Ratifications(context.Context, *QueryRatificationsRequest) (*QueryRatificationsResponse, error)
}

